import re, zlib, sys, collections

class Name(str):
    __slots__=()
class Ref:
    __slots__=('num','gen')
    def __init__(self,num,gen): self.num=num; self.gen=gen
    def __repr__(self): return "Ref(%d)"%self.num
    def __eq__(self,o): return isinstance(o,Ref) and o.num==self.num
    def __hash__(self): return hash(('R',self.num))
class Stream:
    __slots__=('dict','raw','_data')
    def __init__(self,d,raw): self.dict=d; self.raw=raw; self._data=None

WSB=b"\x00\t\n\x0c\r "
DELIMB=b"()<>[]{}/%"

def skip_ws(b,i):
    n=len(b)
    while i<n:
        c=b[i]
        if c in WSB: i+=1
        elif c==0x25:
            while i<n and b[i] not in b"\r\n": i+=1
        else: break
    return i

NUMRE=re.compile(rb'[+-]?(?:\d+\.?\d*|\.\d+)')
REFRE=re.compile(rb'\s*(\d+)\s+(\d+)\s+R(?![a-zA-Z0-9])')

def parse_obj(b,i):
    i=skip_ws(b,i)
    n=len(b)
    if i>=n: return None,i
    c=b[i]
    if c==0x2f: # /
        j=i+1
        while j<n and b[j] not in WSB and b[j] not in DELIMB: j+=1
        raw=b[i+1:j]
        if b'#' in raw:
            raw=re.sub(rb'#([0-9A-Fa-f]{2})',lambda m: bytes([int(m.group(1),16)]),raw)
        return Name(raw.decode('latin-1')),j
    if c==0x28: # (
        depth=1;j=i+1;out=bytearray()
        M={0x6e:10,0x72:13,0x74:9,0x62:8,0x66:12,0x28:40,0x29:41,0x5c:92}
        while j<n:
            ch=b[j]
            if ch==0x5c:
                if j+1>=n: break
                nx=b[j+1]
                if nx in M: out.append(M[nx]); j+=2
                elif 0x30<=nx<=0x37:
                    k=j+1; o=b''
                    while k<n and len(o)<3 and 0x30<=b[k]<=0x37: o+=b[k:k+1]; k+=1
                    out.append(int(o,8)&0xFF); j=k
                elif nx in (10,13):
                    j+=2
                    if nx==13 and j<n and b[j]==10: j+=1
                else: out.append(nx); j+=2
            elif ch==0x28: depth+=1; out.append(ch); j+=1
            elif ch==0x29:
                depth-=1; j+=1
                if depth==0: break
                out.append(0x29)
            else: out.append(ch); j+=1
        return bytes(out),j
    if c==0x3c:
        if i+1<n and b[i+1]==0x3c:
            d={};j=i+2
            while True:
                j=skip_ws(b,j)
                if j>=n: break
                if b[j:j+2]==b'>>': j+=2; break
                k,j2=parse_obj(b,j)
                if not isinstance(k,Name):
                    if j2<=j: j+=1
                    else: j=j2
                    continue
                v,j=parse_obj(b,j2)
                d[str(k)]=v
            return d,j
        e=b.find(b'>',i)
        if e<0: e=n
        hx=re.sub(rb'[^0-9A-Fa-f]',b'',b[i+1:e])
        if len(hx)%2: hx+=b'0'
        return bytes.fromhex(hx.decode()),e+1
    if c==0x5b: # [
        arr=[];j=i+1
        while True:
            j=skip_ws(b,j)
            if j>=n: break
            if b[j]==0x5d: j+=1; break
            v,j2=parse_obj(b,j)
            if j2<=j: j+=1; continue
            arr.append(v); j=j2
        return arr,j
    if c==0x5d: return None,i+1
    if c==0x3e: return None,i+2
    if b[i:i+4]==b'true': return True,i+4
    if b[i:i+5]==b'false': return False,i+5
    if b[i:i+4]==b'null': return None,i+4
    m=NUMRE.match(b,i)
    if m:
        # possible ref
        m2=REFRE.match(b,m.end())
        if m2 and b'.' not in m.group(0):
            try: return Ref(int(m.group(0)),int(m2.group(1))),m2.end()
            except: pass
        m2=re.match(rb'\s*(\d+)\s+R(?![a-zA-Z0-9])',b[m.end():m.end()+30])
        s=m.group(0)
        try:
            if b'.' in s: return float(s),m.end()
            return int(s),m.end()
        except: return 0,m.end()
    # keyword token
    j=i
    while j<n and b[j] not in WSB and b[j] not in DELIMB: j+=1
    if j==i: j=i+1
    return Name('__KW__'+b[i:j].decode('latin-1')),j


def apply_predictor(data,parms,resolve):
    if not parms: return data
    parms={k:resolve(v) for k,v in parms.items()}
    pred=parms.get('Predictor',1) or 1
    if pred<2: return data
    colors=parms.get('Colors',1) or 1
    bpc=parms.get('BitsPerComponent',8) or 8
    columns=parms.get('Columns',1) or 1
    bpp=max(1,(colors*bpc+7)//8)
    rowlen=(columns*colors*bpc+7)//8
    if pred==2:
        return data
    out=bytearray(); prev=bytearray(rowlen)
    i=0
    while i+1<=len(data)-1 or (i<len(data)):
        if i>=len(data): break
        ft=data[i]; i+=1
        row=bytearray(data[i:i+rowlen]); i+=rowlen
        if len(row)<rowlen: row+=bytes(rowlen-len(row))
        if ft==0: pass
        elif ft==1:
            for k in range(bpp,rowlen): row[k]=(row[k]+row[k-bpp])&0xFF
        elif ft==2:
            for k in range(rowlen): row[k]=(row[k]+prev[k])&0xFF
        elif ft==3:
            for k in range(rowlen):
                left=row[k-bpp] if k>=bpp else 0
                row[k]=(row[k]+((left+prev[k])>>1))&0xFF
        elif ft==4:
            for k in range(rowlen):
                a=row[k-bpp] if k>=bpp else 0
                bb=prev[k]; cc=prev[k-bpp] if k>=bpp else 0
                p=a+bb-cc; pa=abs(p-a); pb=abs(p-bb); pc=abs(p-cc)
                pr=a if (pa<=pb and pa<=pc) else (bb if pb<=pc else cc)
                row[k]=(row[k]+pr)&0xFF
        out+=row; prev=row
    return bytes(out)

def lzw_decode(data,early=1):
    out=bytearray(); dic=[bytes([i]) for i in range(256)]+[b'',b'']
    bitpos=0; codelen=9; prev=None
    nbits=len(data)*8
    while bitpos+codelen<=nbits:
        byte=bitpos//8; shift=bitpos%8
        chunk=int.from_bytes(data[byte:byte+3].ljust(3,b'\0'),'big')
        code=(chunk>>(24-shift-codelen))&((1<<codelen)-1)
        bitpos+=codelen
        if code==256:
            dic=dic[:258]; codelen=9; prev=None; continue
        if code==257: break
        if prev is None:
            entry=dic[code]
        else:
            if code<len(dic): entry=dic[code]
            else: entry=prev+prev[:1]
            dic.append(prev+entry[:1])
        out+=entry; prev=entry
        if len(dic)+early>=(1<<codelen) and codelen<12: codelen+=1
    return bytes(out)

def ascii85(data):
    data=data.replace(b'\n',b'').replace(b'\r',b'').replace(b' ',b'').replace(b'\t',b'')
    if data.startswith(b'<~'): data=data[2:]
    e=data.find(b'~>')
    if e>=0: data=data[:e]
    out=bytearray(); grp=[]
    for ch in data:
        if ch==0x7a and not grp: out+=b'\0\0\0\0'; continue
        grp.append(ch-33)
        if len(grp)==5:
            v=0
            for g in grp: v=v*85+g
            out+=v.to_bytes(4,'big'); grp=[]
    if grp:
        k=len(grp)
        grp+= [84]*(5-k); v=0
        for g in grp: v=v*85+g
        out+=v.to_bytes(4,'big')[:k-1]
    return bytes(out)

def asciihex(data):
    e=data.find(b'>')
    if e>=0: data=data[:e]
    hx=re.sub(rb'[^0-9A-Fa-f]',b'',data)
    if len(hx)%2: hx+=b'0'
    return bytes.fromhex(hx.decode())


class PDF:
    def __init__(self,path):
        self.buf=open(path,'rb').read()
        self.objs={}
        self.cache={}
        self._scan()
        self._expand_objstms()
        self.trailer=self._find_trailer()
    def _scan(self):
        for m in re.finditer(rb'(?<![0-9])(\d{1,8})\s+(\d{1,5})\s+obj\b',self.buf):
            self.objs[int(m.group(1))]=('file',m.end())
    def _read_at(self,pos):
        b=self.buf
        v,j=parse_obj(b,pos)
        if isinstance(v,dict):
            j2=skip_ws(b,j)
            if b[j2:j2+6]==b'stream':
                j2+=6
                if b[j2:j2+2]==b'\r\n': j2+=2
                elif j2<len(b) and b[j2] in (10,13): j2+=1
                L=self.resolve(v.get('Length'))
                raw=None
                if isinstance(L,int) and L>=0:
                    raw=b[j2:j2+L]
                    tail=b[j2+L:j2+L+20]
                    if b'endstream' not in tail:
                        raw=None
                if raw is None:
                    e=b.find(b'endstream',j2)
                    raw=b[j2:e if e>=0 else len(b)]
                    if raw.endswith(b'\r\n'): raw=raw[:-2]
                    elif raw.endswith(b'\n') or raw.endswith(b'\r'): raw=raw[:-1]
                return Stream(v,raw)
        return v
    def get(self,num):
        if num in self.cache: return self.cache[num]
        e=self.objs.get(num)
        if e is None: return None
        self.cache[num]=None
        if e[0]=='file': val=self._read_at(e[1])
        else: val=e[1]
        self.cache[num]=val
        return val
    def resolve(self,o,depth=0):
        while isinstance(o,Ref) and depth<64:
            o=self.get(o.num); depth+=1
        return o
    def data(self,st):
        st=self.resolve(st)
        if not isinstance(st,Stream): return b''
        if st._data is not None: return st._data
        d=st.raw
        filt=self.resolve(st.dict.get('Filter'))
        parms=self.resolve(st.dict.get('DecodeParms')) or self.resolve(st.dict.get('DP'))
        if filt is None: filts=[]
        elif isinstance(filt,list): filts=[self.resolve(f) for f in filt]
        else: filts=[filt]
        if parms is None: parml=[None]*len(filts)
        elif isinstance(parms,list): parml=[self.resolve(p) for p in parms]
        else: parml=[parms]+[None]*(len(filts)-1)
        for f,p in zip(filts,parml):
            f=str(f)
            try:
                if f in ('FlateDecode','Fl'):
                    try: d=zlib.decompress(d)
                    except Exception:
                        do=zlib.decompressobj()
                        try: d=do.decompress(d)
                        except Exception:
                            d=zlib.decompressobj(-15).decompress(d[2:] if d[:1]==b'\x78' else d)
                    d=apply_predictor(d,p,self.resolve)
                elif f in ('LZWDecode','LZW'):
                    early=1
                    if p: early=self.resolve(p.get('EarlyChange',1))
                    d=lzw_decode(d,early if early is not None else 1)
                    d=apply_predictor(d,p,self.resolve)
                elif f in ('ASCII85Decode','A85'): d=ascii85(d)
                elif f in ('ASCIIHexDecode','AHx'): d=asciihex(d)
                else: pass
            except Exception as ex:
                pass
        st._data=d
        return d
    def _expand_objstms(self):
        nums=list(self.objs.keys())
        for num in nums:
            e=self.objs.get(num)
            if not e or e[0]!='file': continue
            # peek type quickly
            pos=e[1]
            snippet=self.buf[pos:pos+400]
            if b'/ObjStm' not in snippet: continue
            st=self.get(num)
            if not isinstance(st,Stream): continue
            try:
                d=self.data(st)
                N=self.resolve(st.dict.get('N')); first=self.resolve(st.dict.get('First'))
                hdr=d[:first].split()
                pairs=[(int(hdr[i]),int(hdr[i+1])) for i in range(0,len(hdr)-1,2)][:N]
                for onum,off in pairs:
                    if onum in self.objs and self.objs[onum][0]=='file': continue
                    v,_=parse_obj(d,first+off)
                    self.objs[onum]=('inline',v)
            except Exception: pass
    def _find_trailer(self):
        tr={}
        for m in re.finditer(rb'trailer',self.buf):
            d,_=parse_obj(self.buf,m.end())
            if isinstance(d,dict):
                for k,v in d.items():
                    if k not in tr: tr[k]=v
        if 'Root' not in tr:
            for num,e in self.objs.items():
                o=self.get(num)
                if isinstance(o,Stream) and str(self.resolve(o.dict.get('Type')))=='XRef':
                    if 'Root' in o.dict: tr['Root']=o.dict['Root']; break
        if 'Root' not in tr:
            for num in list(self.objs):
                o=self.get(num)
                if isinstance(o,dict) and str(self.resolve(o.get('Type')))=='Catalog':
                    tr['Root']=Ref(num,0); break
        return tr
    @property
    def root(self): return self.resolve(self.trailer.get('Root')) or {}
    def pages(self):
        if hasattr(self,'_pages'): return self._pages
        out=[]
        seen=set()
        def walk(node,inh):
            node=self.resolve(node)
            if not isinstance(node,dict): return
            inh=dict(inh)
            for k in ('Resources','MediaBox','CropBox','Rotate'):
                if k in node: inh[k]=node[k]
            t=str(self.resolve(node.get('Type')) or '')
            kids=self.resolve(node.get('Kids'))
            if t=='Page' or (kids is None and 'Contents' in node):
                m=dict(node); 
                for k,v in inh.items(): m.setdefault(k,v)
                out.append(m); return
            if isinstance(kids,list):
                for kd in kids:
                    key=kd.num if isinstance(kd,Ref) else id(kd)
                    if key in seen: continue
                    seen.add(key)
                    walk(kd,inh)
        walk(self.root.get('Pages'),{})
        if not out:
            for num in sorted(self.objs):
                o=self.get(num)
                if isinstance(o,dict) and str(self.resolve(o.get('Type')))=='Page':
                    out.append(o)
        self._pages=out
        # map page object ref -> index
        self._pagerefmap={}
        idx=0
        # rebuild with refs
        return out
    def page_index_map(self):
        if hasattr(self,'_pim'): return self._pim
        pim={}
        seen=set()
        counter=[0]
        def walk(ref):
            node=self.resolve(ref)
            if not isinstance(node,dict): return
            t=str(self.resolve(node.get('Type')) or '')
            kids=self.resolve(node.get('Kids'))
            if t=='Page' or (kids is None and 'Contents' in node):
                if isinstance(ref,Ref): pim[ref.num]=counter[0]
                counter[0]+=1
                return
            if isinstance(kids,list):
                for kd in kids:
