class FontInfo:
    def __init__(self,pdf,fd):
        self.two=False; self.map={}; self.ok=False
        fd=pdf.resolve(fd)
        if not isinstance(fd,dict): return
        st=str(pdf.resolve(fd.get('Subtype')) or '')
        enc=pdf.resolve(fd.get('Encoding'))
        encname=str(enc) if isinstance(enc,Name) else ''
        if st=='Type0':
            self.two=True
            if 'Identity' in encname: self.two=True
        tu=fd.get('ToUnicode')
        if tu is not None:
            try:
                self.map=parse_tounicode(pdf.data(tu)); self.ok=bool(self.map)
            except Exception: pass
        # differences encoding for simple fonts
        self.diff={}
        if isinstance(enc,dict):
            dl=pdf.resolve(enc.get('Differences'))
            if isinstance(dl,list):
                cur=0
                for it in dl:
                    it=pdf.resolve(it)
                    if isinstance(it,(int,float)): cur=int(it)
                    elif isinstance(it,Name):
                        self.diff[cur]=glyphname_to_unicode(str(it)); cur+=1
    def decode(self,bs):
        out=[]
        if self.two:
            for i in range(0,len(bs)-1,2):
                c=(bs[i]<<8)|bs[i+1]
                out.append(self.map.get(c, chr(c) if not self.map else ''))
            return ''.join(out)
        for ch in bs:
            if ch in self.map: out.append(self.map[ch])
            elif ch in self.diff: out.append(self.diff[ch])
            else: out.append(bytes([ch]).decode('latin-1'))
        return ''.join(out)

